  const bg = new Mesh(bgGeom, bgMat);
  bg.position.set(0, 0, -2.5);
  group.add(bg);

  // Gradient via TSL
  const bgColorTop = vec3(0.043, 0.043, 0.063);
  const bgColorBottom = vec3(0.09, 0.09, 0.11);
  bgMat.colorNode = mix(bgColorBottom, bgColorTop, smoothstep(float(0.0), float(1.0), uv().y));

  // 2. Main text plane (transparent, just holds the visual elements)
  const planeMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.0 });
